import{_ as d,o as e,c as r,a4 as a}from"./chunks/framework.BMj-uaUw.js";const b=JSON.parse('{"title":"三阶段交付","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、三个阶段总览","slug":"一、三个阶段总览","link":"#一、三个阶段总览","children":[]},{"level":2,"title":"二、阶段一 · 立项与骨架（第 1 - 3 周）","slug":"二、阶段一-·-立项与骨架-第-1-3-周","link":"#二、阶段一-·-立项与骨架-第-1-3-周","children":[{"level":3,"title":"目标","slug":"目标","link":"#目标","children":[]},{"level":3,"title":"逐周产出","slug":"逐周产出","link":"#逐周产出","children":[]},{"level":3,"title":"这个阶段要交的两份清单","slug":"这个阶段要交的两份清单","link":"#这个阶段要交的两份清单","children":[]},{"level":3,"title":"阶段一的检查点","slug":"阶段一的检查点","link":"#阶段一的检查点","children":[]}]},{"level":2,"title":"三、阶段二 · 功能实现（第 4 - 10 周）","slug":"三、阶段二-·-功能实现-第-4-10-周","link":"#三、阶段二-·-功能实现-第-4-10-周","children":[{"level":3,"title":"目标","slug":"目标-1","link":"#目标-1","children":[]},{"level":3,"title":"单元与项目模块的对应关系","slug":"单元与项目模块的对应关系","link":"#单元与项目模块的对应关系","children":[]},{"level":3,"title":"逐周产出与验收","slug":"逐周产出与验收","link":"#逐周产出与验收","children":[]},{"level":3,"title":"阶段二的检查点","slug":"阶段二的检查点","link":"#阶段二的检查点","children":[]}]},{"level":2,"title":"四、阶段三 · 交付（第 11 - 12 周）","slug":"四、阶段三-·-交付-第-11-12-周","link":"#四、阶段三-·-交付-第-11-12-周","children":[{"level":3,"title":"目标","slug":"目标-2","link":"#目标-2","children":[]},{"level":3,"title":"第 11 周 · 项目启动与核心业务","slug":"第-11-周-·-项目启动与核心业务","link":"#第-11-周-·-项目启动与核心业务","children":[]},{"level":3,"title":"第 12 周 · 联调、优化、部署、答辩","slug":"第-12-周-·-联调、优化、部署、答辩","link":"#第-12-周-·-联调、优化、部署、答辩","children":[]},{"level":3,"title":"阶段三的检查点","slug":"阶段三的检查点","link":"#阶段三的检查点","children":[]}]},{"level":2,"title":"五、延伸 · 用户端（选做）","slug":"五、延伸-·-用户端-选做","link":"#五、延伸-·-用户端-选做","children":[{"level":3,"title":"目标","slug":"目标-3","link":"#目标-3","children":[]},{"level":3,"title":"逐篇产出","slug":"逐篇产出","link":"#逐篇产出","children":[]},{"level":3,"title":"用户端特有的坑","slug":"用户端特有的坑","link":"#用户端特有的坑","children":[]}]},{"level":2,"title":"六、每周的自查清单","slug":"六、每周的自查清单","link":"#六、每周的自查清单","children":[]},{"level":2,"title":"七、阶段性交付物清单","slug":"七、阶段性交付物清单","link":"#七、阶段性交付物清单","children":[{"level":3,"title":"阶段一（第 3 周）","slug":"阶段一-第-3-周","link":"#阶段一-第-3-周","children":[]},{"level":3,"title":"阶段二（第 10 周）","slug":"阶段二-第-10-周","link":"#阶段二-第-10-周","children":[]},{"level":3,"title":"阶段三（第 12 周）","slug":"阶段三-第-12-周","link":"#阶段三-第-12-周","children":[]},{"level":3,"title":"延伸 · 用户端（选做，第 12 周之后）","slug":"延伸-·-用户端-选做-第-12-周之后","link":"#延伸-·-用户端-选做-第-12-周之后","children":[]}]},{"level":2,"title":"八、常见的时间陷阱","slug":"八、常见的时间陷阱","link":"#八、常见的时间陷阱","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"project/milestones.md","filePath":"project/milestones.md","lastUpdated":1789500889000}'),o={name:"project/milestones.md"};function l(n,t,i,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="三阶段交付" tabindex="-1">三阶段交付 <a class="header-anchor" href="#三阶段交付" aria-label="Permalink to &quot;三阶段交付&quot;">​</a></h1><p>这一页把 12 周拆成三个交付阶段，每周给出一个<strong>可检查的产出</strong>。</p><p><strong>为什么要分阶段</strong>：项目最大的风险不是“做不出来”，是“最后一周发现前面有个东西没做，来不及补”。</p><p>分阶段交付的作用是<strong>让问题尽早暴露</strong>。每周都有一个能拿得出手的东西，做不动了立刻能发现。</p><h2 id="一、三个阶段总览" tabindex="-1">一、三个阶段总览 <a class="header-anchor" href="#一、三个阶段总览" aria-label="Permalink to &quot;一、三个阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>周次</th><th>主题</th><th>阶段结束时的状态</th></tr></thead><tbody><tr><td>阶段一</td><td>第 1 - 3 周</td><td>立项与骨架</td><td>需求清单齐全、工程能跑起来、规范配置就位</td></tr><tr><td>阶段二</td><td>第 4 - 10 周</td><td>功能实现</td><td>五个模块的页面与逻辑都做出来，接上数据</td></tr><tr><td>阶段三</td><td>第 11 - 12 周</td><td>交付</td><td>主线跑通、有优化数据、有线上地址、有文档</td></tr><tr><td>延伸</td><td>阶段三之后</td><td>用户端（选做）</td><td>手机端 5 个页面能跑，H5 或小程序发布出去</td></tr></tbody></table><p><strong>三个阶段的交付物是层叠的</strong>：阶段一不完成，阶段二写的代码没有地方放；阶段二不完成，阶段三没有东西可以部署。</p><p>最后一行不算阶段，是<strong>选做的延伸内容</strong>。用户端不占课时，管理端交完再做，两周左右能完成， 也完全可以放到课程结束之后自己练。</p><h2 id="二、阶段一-·-立项与骨架-第-1-3-周" tabindex="-1">二、阶段一 · 立项与骨架（第 1 - 3 周） <a class="header-anchor" href="#二、阶段一-·-立项与骨架-第-1-3-周" aria-label="Permalink to &quot;二、阶段一 · 立项与骨架（第 1 - 3 周）&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>把“要做什么”和“在哪写”定下来。<strong>这个阶段不写业务代码。</strong></p><h3 id="逐周产出" tabindex="-1">逐周产出 <a class="header-anchor" href="#逐周产出" aria-label="Permalink to &quot;逐周产出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>对应单元</th><th>产出</th><th>验收标准</th></tr></thead><tbody><tr><td>第 1 周</td><td>单元 1</td><td>环境自检报告、个人学习路线图</td><td>环境自检清单逐项通过；路线图写出了“已过关 / 未过关”</td></tr><tr><td>第 2 周</td><td>单元 2</td><td>一个跑得起来的 Vite 工程、依赖清单</td><td><code>pnpm dev</code> 能启动；<code>package.json</code> 里有路由、状态、请求、UI 库四项依赖</td></tr><tr><td>第 3 周</td><td>单元 3</td><td>代码规范配置、Git 仓库、目录结构</td><td>故意写一行不合规范的代码，提交被拦下；<code>git log</code> 里的提交信息符合规范</td></tr></tbody></table><h3 id="这个阶段要交的两份清单" tabindex="-1">这个阶段要交的两份清单 <a class="header-anchor" href="#这个阶段要交的两份清单" aria-label="Permalink to &quot;这个阶段要交的两份清单&quot;">​</a></h3><p><strong>这两份清单来自<a href="/frontend-engineering-course/project/requirements.html">需求规格说明</a>和<a href="/frontend-engineering-course/unit11/01-requirements.html">11.1 从需求到页面清单</a>。</strong></p><p><strong>清单一：页面清单与路由表</strong></p><p>覆盖五个模块的 12 个页面。格式：</p><table tabindex="0"><thead><tr><th>页面</th><th>路由</th><th>主要接口</th><th>可访问角色</th></tr></thead><tbody><tr><td>活动列表</td><td><code>/activity</code></td><td><code>GET /api/activities</code></td><td>组织者、审核员</td></tr></tbody></table><p><strong>清单二：接口清单</strong></p><p>和后面 <a href="/frontend-engineering-course/project/api.html">接口约定</a>对齐。重点确认三件事：</p><ol><li>统一响应结构里成功码是几</li><li>分页字段叫什么</li><li>时间格式是什么</li></ol><h3 id="阶段一的检查点" tabindex="-1">阶段一的检查点 <a class="header-anchor" href="#阶段一的检查点" aria-label="Permalink to &quot;阶段一的检查点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查点</th><th>在第几周查</th><th>不过会怎样</th></tr></thead><tbody><tr><td>环境能跑起来</td><td>第 1 周</td><td>第 2 周所有实操都做不了</td></tr><tr><td>页面清单写完了</td><td>第 3 周</td><td>第 4 周开始写路由表时会反复改</td></tr><tr><td>接口约定定下来了</td><td>第 3 周</td><td>第 9、10 周联调时会大面积返工</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">阶段一最容易被跳过，也最不该跳过</p><p>很多同学觉得“写清单是浪费时间，不如直接开始写代码”。</p><p><strong>代价在第 11 周才会显现</strong>：做到一半发现“报名审核”该放在活动详情里还是单独一个菜单项，两边的代码都写了一半，只能挑一个推翻重来。</p><p><strong>第 3 周的那两份清单，能省掉第 11 周的两个小时。</strong></p><p><strong>怎么判断清单写得够不够</strong>：找一个同学，把你的清单给他看，问他“这个页面点进去是什么样”。他答得出来，说明写清楚了；他反问“这里是什么意思”，说明那一处还没想清楚。</p></div><h2 id="三、阶段二-·-功能实现-第-4-10-周" tabindex="-1">三、阶段二 · 功能实现（第 4 - 10 周） <a class="header-anchor" href="#三、阶段二-·-功能实现-第-4-10-周" aria-label="Permalink to &quot;三、阶段二 · 功能实现（第 4 - 10 周）&quot;">​</a></h2><h3 id="目标-1" tabindex="-1">目标 <a class="header-anchor" href="#目标-1" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>把五个模块的页面和逻辑都做出来。<strong>这个阶段每个单元的案例都直接对应项目的模块。</strong></p><h3 id="单元与项目模块的对应关系" tabindex="-1">单元与项目模块的对应关系 <a class="header-anchor" href="#单元与项目模块的对应关系" aria-label="Permalink to &quot;单元与项目模块的对应关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>单元</th><th>学什么</th><th>用在项目的哪一部分</th></tr></thead><tbody><tr><td>第 4 周</td><td>单元 4</td><td>模板语法与响应式</td><td>任何一个页面的基础</td></tr><tr><td>第 5 周</td><td>单元 5</td><td>计算属性与渲染控制</td><td><strong>活动列表页</strong>（案例 01 增删改查、案例 02 数据表格）</td></tr><tr><td>第 6 周</td><td>单元 6</td><td>交互与表单绑定</td><td><strong>活动新增 / 编辑表单</strong>（案例 05 Markdown 编辑器对应活动说明字段）</td></tr><tr><td>第 7 周</td><td>单元 7</td><td>组件基础与父子通信</td><td><strong>场次与场地</strong>（案例 03 树状视图对应组织架构、案例 09 可编辑表格对应场次时段编辑）</td></tr><tr><td>第 8 周</td><td>单元 8</td><td>组件进阶与逻辑复用</td><td><strong>模态框与全局通知</strong>（案例 06 对应审核确认与操作提示、案例 08 画板是扩展练习）</td></tr><tr><td>第 9 周</td><td>单元 9</td><td>路由与登录鉴权</td><td><strong>登录鉴权模块</strong>（案例 10 直接就是这一模块）</td></tr><tr><td>第 10 周</td><td>单元 10</td><td>Pinia 与请求层</td><td><strong>所有模块的数据层</strong>（案例 04 从接口获取数据）</td></tr></tbody></table><p><strong>这张表的意思是：每周的案例练习不是额外作业，它们拼起来就是项目。</strong></p><p><strong>如果你每周都认真做了案例，第 11 周开始时项目应该已经完成七八成。</strong></p><h3 id="逐周产出与验收" tabindex="-1">逐周产出与验收 <a class="header-anchor" href="#逐周产出与验收" aria-label="Permalink to &quot;逐周产出与验收&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>产出</th><th>验收标准</th></tr></thead><tbody><tr><td>第 4 周</td><td>一个能双向绑定的页面</td><td>输入框改内容，页面上的文字跟着变</td></tr><tr><td>第 5 周</td><td>活动列表页（本地假数据）</td><td>能查询、能分页、四态齐全；增删改查都能操作</td></tr><tr><td>第 6 周</td><td>活动表单页（本地假数据）</td><td>校验能触发；提交有 loading；离开未保存会提醒</td></tr><tr><td>第 7 周</td><td>场次列表 + 场地组件拆分</td><td>组件拆分合理；父子通信用的是 props 与 emits</td></tr><tr><td>第 8 周</td><td>模态框与全局通知</td><td>审核确认用模态框；操作结果用全局通知提示</td></tr><tr><td>第 9 周</td><td>登录页 + 路由守卫</td><td>未登录访问后台会被拦；登录后能进入</td></tr><tr><td>第 10 周</td><td>请求层 + 用户 Store</td><td>接口调用统一走 <code>api/</code> 层；token 能自动携带</td></tr></tbody></table><h3 id="阶段二的检查点" tabindex="-1">阶段二的检查点 <a class="header-anchor" href="#阶段二的检查点" aria-label="Permalink to &quot;阶段二的检查点&quot;">​</a></h3><p><strong>每周都要问自己三个问题：</strong></p><table tabindex="0"><thead><tr><th>问题</th><th>如果答案是“否”</th></tr></thead><tbody><tr><td>这周做的东西，能不能独立跑起来看？</td><td>说明依赖了下周的内容，顺序有问题</td></tr><tr><td>有没有把代码放进 <a href="/frontend-engineering-course/project/structure.html">约定的目录</a>？</td><td>拖延改目录的代价随时间指数上升</td></tr><tr><td>提交历史是不是还有意义的？</td><td>攒到最后一次性提交，出问题无法回退</td></tr></tbody></table><details class="details custom-block"><summary>第 5、6 周是最容易落后的时间点</summary><p>这两周的内容量最大（列表页和表单页），而且要求第一次把“页面 + 数据 + 交互”串起来。</p><p><strong>落后了怎么办</strong>：<strong>不要跳过案例直接做项目。</strong> 案例是拆解过的、有验收标准的小练习；项目是完整的、要自己拆解的。跳过案例做项目，相当于不做练习直接考试。</p><p><strong>正确的做法是降低项目部分的完成度，保证案例做完。</strong> 项目先只做“活动列表 + 活动表单”这条最核心的链路，其余模块在第 11、12 周补。</p><p><strong>判断标准</strong>：到第 6 周结束，你应该有一个“能查、能填、能存（本地）”的活动管理模块。这是主线的基础。</p></details><h2 id="四、阶段三-·-交付-第-11-12-周" tabindex="-1">四、阶段三 · 交付（第 11 - 12 周） <a class="header-anchor" href="#四、阶段三-·-交付-第-11-12-周" aria-label="Permalink to &quot;四、阶段三 · 交付（第 11 - 12 周）&quot;">​</a></h2><h3 id="目标-2" tabindex="-1">目标 <a class="header-anchor" href="#目标-2" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>把项目从“本地能跑”变成“别人能用”。</p><h3 id="第-11-周-·-项目启动与核心业务" tabindex="-1">第 11 周 · 项目启动与核心业务 <a class="header-anchor" href="#第-11-周-·-项目启动与核心业务" aria-label="Permalink to &quot;第 11 周 · 项目启动与核心业务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>对应单元</td><td>单元 11</td></tr><tr><td>学什么</td><td>从需求到清单、工程初始化、布局骨架、列表页与表单页的标准做法</td></tr><tr><td>产出</td><td>① 页面清单与接口清单 ② 可运行的工程骨架 ③ 活动管理模块的列表页与表单页</td></tr><tr><td>验收</td><td>见<a href="/frontend-engineering-course/unit11/practice.html">单元 11 课后练习</a>的四道必做题</td></tr></tbody></table><p><strong>这一周的实际任务是“把阶段二散着做的页面装进一个完整的壳里”：</strong></p><table tabindex="0"><thead><tr><th>阶段二做了什么</th><th>阶段三要补什么</th></tr></thead><tbody><tr><td>活动列表页、表单页（本地假数据）</td><td>换成真实的接口调用；补四态</td></tr><tr><td>各模块的组件</td><td>装进统一的布局（侧边栏 + 顶栏 + 面包屑）</td></tr><tr><td>零散的路由</td><td>整理成 <a href="/frontend-engineering-course/unit11/03-layout.html">结构化的路由表</a></td></tr><tr><td>页面各自判断状态</td><td>抽出 <a href="/frontend-engineering-course/project/structure.html">domain 规则模块</a></td></tr></tbody></table><h3 id="第-12-周-·-联调、优化、部署、答辩" tabindex="-1">第 12 周 · 联调、优化、部署、答辩 <a class="header-anchor" href="#第-12-周-·-联调、优化、部署、答辩" aria-label="Permalink to &quot;第 12 周 · 联调、优化、部署、答辩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>对应单元</td><td>单元 12</td></tr><tr><td>学什么</td><td>前后端联调、构建优化、部署上线、交付与答辩</td></tr><tr><td>产出</td><td>① 联调记录表 ② 优化前后对比数据 ③ 线上地址 ④ 交付文档与答辩 PPT</td></tr><tr><td>验收</td><td>见<a href="/frontend-engineering-course/unit12/practice.html">单元 12 课后练习</a>的四道必做题</td></tr></tbody></table><h3 id="阶段三的检查点" tabindex="-1">阶段三的检查点 <a class="header-anchor" href="#阶段三的检查点" aria-label="Permalink to &quot;阶段三的检查点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>检查什么</th><th>不通过怎么办</th></tr></thead><tbody><tr><td>第 11 周初</td><td>阶段二的页面是不是都能跑？</td><td>先只保证活动管理这条链路，其余模块后补</td></tr><tr><td>第 11 周末</td><td>活动管理模块能不能查、能填、能存？</td><td>这是主线的基础，必须完成</td></tr><tr><td>第 12 周初</td><td>前后端接口对上了吗？</td><td>没对上就先用 mock，把前端逻辑跑通</td></tr><tr><td>第 12 周中</td><td>有没有部署上去？</td><td><strong>这是硬性要求</strong>，其他都可以降级，这个不能</td></tr><tr><td>第 12 周末</td><td>六份交付材料齐了吗？</td><td>缺哪份补哪份，文档比功能重要</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">第 12 周的两件事不能拖到最后一天</p><p><strong>一、部署。</strong> 部署一定会遇到问题（子路由 404、接口地址不对、跨域）。<strong>这些问题在最后一天才发现，就没有时间修了。</strong></p><p><strong>建议：第 12 周的第一天就把项目部署上去。</strong> 哪怕功能还没做完，先部署一个半成品 —— 这样后面每加一个功能都能立刻验证。</p><p><strong>二、答辩 PPT。</strong> 有同学觉得“东西都在脑子里，到时候讲就行”。<strong>实际讲的时候会卡、会漏、会超时。</strong></p><p><strong>提前三天做好 PPT 并排练三遍</strong>，比最后一天熬夜做效果好几倍。排练的方法见 <a href="/frontend-engineering-course/unit12/04-delivery.html">12.4 交付材料与答辩</a>。</p><p><strong>这两件事的共同点是：它们的失败是可以提前发现的，而且发现的成本很低。</strong> 不做就只能等它真的失败。</p></div><h2 id="五、延伸-·-用户端-选做" tabindex="-1">五、延伸 · 用户端（选做） <a class="header-anchor" href="#五、延伸-·-用户端-选做" aria-label="Permalink to &quot;五、延伸 · 用户端（选做）&quot;">​</a></h2><p>管理端交付完之后，如果还有时间，可以接着做<a href="/frontend-engineering-course/mobile/">用户端</a>。它不占课时，两周左右能完成。</p><h3 id="目标-3" tabindex="-1">目标 <a class="header-anchor" href="#目标-3" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>把同一套后端接口接到手机上。<strong>技术难点不在 Vue 语法，在跨端框架的那些差异。</strong></p><h3 id="逐篇产出" tabindex="-1">逐篇产出 <a class="header-anchor" href="#逐篇产出" aria-label="Permalink to &quot;逐篇产出&quot;">​</a></h3><p>用户端是 11 篇独立专栏，不按周编号。按顺序做下来，产出是这样：</p><table tabindex="0"><thead><tr><th>做完哪几篇</th><th>产出</th><th>验收标准</th></tr></thead><tbody><tr><td>篇 1 - 2</td><td>能跑起来的 uni-app 工程</td><td><code>pnpm dev:h5</code> 打开浏览器能看到首页；<code>pnpm dev:mp-weixin</code> 的产物能用微信开发者工具打开</td></tr><tr><td>篇 3 - 5</td><td>5 个页面 + 路由表</td><td>tabBar 能切换；列表页点进详情不报错</td></tr><tr><td>篇 6 - 8</td><td>请求层 + 登录态 + 三个业务页</td><td>token 能自动携带；未登录点报名会提示并跳登录</td></tr><tr><td>篇 9</td><td>H5 或小程序发布</td><td>手机上能打开，能完整走一遍报名流程</td></tr><tr><td>篇 10</td><td>跨端代码的验收清单</td><td>对着清单逐条检查过自己的代码</td></tr></tbody></table><h3 id="用户端特有的坑" tabindex="-1">用户端特有的坑 <a class="header-anchor" href="#用户端特有的坑" aria-label="Permalink to &quot;用户端特有的坑&quot;">​</a></h3><p>这些坑在管理端不会遇到，动手之前先看一眼：</p><table tabindex="0"><thead><tr><th>坑</th><th>表现</th><th>在哪一篇讲</th></tr></thead><tbody><tr><td>版本对不上</td><td>手动把 Vite 升到 8，编译直接失败</td><td><a href="/frontend-engineering-course/mobile/">用户端总览</a></td></tr><tr><td>单位用错</td><td>用了 px，大屏手机上元素小得看不见</td><td><a href="/frontend-engineering-course/mobile/04-layout-style.html">4. 布局与样式</a></td></tr><tr><td>组件库包名</td><td>按旧包名 <code>wot-design-uni</code> 装，版本停在 1.x</td><td><a href="/frontend-engineering-course/mobile/05-components.html">5. 组件与组件库</a></td></tr><tr><td>表单 API 不一样</td><td>用了 <code>rules</code> 和 <code>label</code>，校验不触发、标签也不显示</td><td><a href="/frontend-engineering-course/mobile/05-components.html">5. 组件与组件库</a></td></tr><tr><td>toast 不显示</td><td>忘了在模板里写 <code>&lt;wd-toast /&gt;</code></td><td><a href="/frontend-engineering-course/mobile/05-components.html">5. 组件与组件库</a></td></tr><tr><td>新页面 404</td><td>加了 <code>.vue</code> 文件，但没往 <code>pages.json</code> 里注册</td><td><a href="/frontend-engineering-course/mobile/03-pages-router.html">3. 页面与路由</a></td></tr><tr><td>没有全局路由守卫</td><td>照 vue-router 的写法写 <code>beforeEach</code>，不生效</td><td><a href="/frontend-engineering-course/mobile/06-request-auth.html">6. 请求封装与登录态</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">做完用户端，答辩能多讲一个技术难点</p><p>答辩要求“讲清一个技术难点”。管理端的难点（名额并发、时段冲突）各组都差不多， 跨端适配是个不一样的点 —— 比如“为什么小程序里拿不到 <code>window</code>”， 或者“为什么要用条件编译分开处理 H5 与微信小程序”。能讲清这个，比再讲一遍列表页分页有说服力。</p></div><h2 id="六、每周的自查清单" tabindex="-1">六、每周的自查清单 <a class="header-anchor" href="#六、每周的自查清单" aria-label="Permalink to &quot;六、每周的自查清单&quot;">​</a></h2><p>不要等到阶段检查才发现问题。<strong>每周花十分钟填一次这张表：</strong></p><table tabindex="0"><thead><tr><th>自查项</th><th>第 N 周</th></tr></thead><tbody><tr><td>本周案例做完了吗？</td><td></td></tr><tr><td>代码提交了吗？提交信息有意义吗？</td><td></td></tr><tr><td>有没有把代码放错目录？</td><td></td></tr><tr><td>有没有出现“先放着，以后再改”的重复代码？</td><td></td></tr><tr><td>项目主线比上周多跑通了什么？</td><td></td></tr><tr><td>这周写的代码我都读过、能解释吗？</td><td></td></tr><tr><td>有卡住超过两小时的问题吗？</td><td></td></tr></tbody></table><p><strong>最后一项最关键。</strong> 卡住超过两小时，说明方向可能错了，或者缺一个知识点。<strong>继续硬撑的代价远大于问一次人。</strong></p><p><strong>“项目主线比上周多跑通了什么”这一项要能写出具体的东西</strong>，不能写“继续完善”。写不出来说明这一周其实没进展。</p><h2 id="七、阶段性交付物清单" tabindex="-1">七、阶段性交付物清单 <a class="header-anchor" href="#七、阶段性交付物清单" aria-label="Permalink to &quot;七、阶段性交付物清单&quot;">​</a></h2><p>项目结束时，这些东西应该都在。</p><h3 id="阶段一-第-3-周" tabindex="-1">阶段一（第 3 周） <a class="header-anchor" href="#阶段一-第-3-周" aria-label="Permalink to &quot;阶段一（第 3 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>交付物</th><th>位置</th><th>状态</th></tr></thead><tbody><tr><td>环境自检报告</td><td>课程作业提交</td><td></td></tr><tr><td>学习路线图</td><td>课程作业提交</td><td></td></tr><tr><td>页面清单与路由表</td><td>项目仓库 <code>docs/design.md</code></td><td></td></tr><tr><td>接口清单</td><td>项目仓库 <code>docs/api.md</code></td><td></td></tr><tr><td>可运行的工程骨架</td><td>项目仓库</td><td></td></tr><tr><td>代码规范配置</td><td>项目仓库（<code>.eslintrc</code> / <code>prettier</code> / <code>husky</code>）</td><td></td></tr><tr><td>AGENTS.md</td><td>项目仓库根目录</td><td></td></tr></tbody></table><h3 id="阶段二-第-10-周" tabindex="-1">阶段二（第 10 周） <a class="header-anchor" href="#阶段二-第-10-周" aria-label="Permalink to &quot;阶段二（第 10 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>交付物</th><th>位置</th><th>状态</th></tr></thead><tbody><tr><td>五个模块的页面文件</td><td><code>src/views/</code></td><td></td></tr><tr><td>组件拆分</td><td><code>src/components/</code> 与 <code>src/views/xxx/components/</code></td><td></td></tr><tr><td>请求层</td><td><code>src/api/</code></td><td></td></tr><tr><td>状态管理</td><td><code>src/stores/</code></td><td></td></tr><tr><td>业务规则</td><td><code>src/domain/</code></td><td></td></tr><tr><td>单元案例练习的代码</td><td>提交到课程作业或独立分支</td><td></td></tr></tbody></table><h3 id="阶段三-第-12-周" tabindex="-1">阶段三（第 12 周） <a class="header-anchor" href="#阶段三-第-12-周" aria-label="Permalink to &quot;阶段三（第 12 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>交付物</th><th>位置</th><th>状态</th></tr></thead><tbody><tr><td>主线功能完整可用</td><td>线上环境</td><td></td></tr><tr><td>线上可访问地址</td><td>写进 README</td><td></td></tr><tr><td>README 完整</td><td>仓库根目录</td><td></td></tr><tr><td>设计文档（含关键决策与代价）</td><td><code>docs/design.md</code></td><td></td></tr><tr><td>接口文档（含错误码表）</td><td><code>docs/api.md</code></td><td></td></tr><tr><td>部署文档（含 Nginx 配置）</td><td><code>docs/deploy.md</code></td><td></td></tr><tr><td>开发记录（含联调问题表）</td><td><code>docs/dev-notes.md</code></td><td></td></tr><tr><td>优化记录（含前后数据）</td><td><code>docs/optimization.md</code></td><td></td></tr><tr><td>AI 参与声明</td><td>项目仓库 <code>docs/ai-usage.md</code></td><td></td></tr><tr><td>答辩 PPT</td><td>课程作业提交</td><td></td></tr><tr><td>演示录屏</td><td>本地备份</td><td></td></tr><tr><td>项目复盘（不用交）</td><td>自己留档</td><td></td></tr></tbody></table><h3 id="延伸-·-用户端-选做-第-12-周之后" tabindex="-1">延伸 · 用户端（选做，第 12 周之后） <a class="header-anchor" href="#延伸-·-用户端-选做-第-12-周之后" aria-label="Permalink to &quot;延伸 · 用户端（选做，第 12 周之后）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>交付物</th><th>位置</th><th>状态</th></tr></thead><tbody><tr><td>用户端工程</td><td>独立的 <code>activity-mobile/</code> 仓库，或主仓库的 <code>mobile/</code> 子目录</td><td></td></tr><tr><td>5 个页面</td><td><code>src/pages/</code> 下（列表、详情、报名、我的报名、个人中心）</td><td></td></tr><tr><td>请求层与登录态工具</td><td><code>src/utils/request.js</code>、<code>src/utils/auth.js</code></td><td></td></tr><tr><td>用户端 README</td><td>工程根目录，写清 <code>dev:h5</code> 与 <code>dev:mp-weixin</code> 的区别</td><td></td></tr><tr><td>H5 线上地址或小程序体验版二维码</td><td>写进 README 与答辩 PPT</td><td></td></tr></tbody></table><h2 id="八、常见的时间陷阱" tabindex="-1">八、常见的时间陷阱 <a class="header-anchor" href="#八、常见的时间陷阱" aria-label="Permalink to &quot;八、常见的时间陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>表现</th><th>怎么避免</th></tr></thead><tbody><tr><td>先做 UI 细节</td><td>前两周反复调颜色和间距</td><td><strong>功能优先。</strong> 样式等到第 11 周统一收拾</td></tr><tr><td>同时做多个模块</td><td>五个模块各做了 30%，一个完整的都没有</td><td><strong>一次做完一个模块。</strong> 完成的模块比半成品有价值</td></tr><tr><td>跳过案例直接做项目</td><td>第 6 周就卡住了</td><td>案例是拆解过的练习，<strong>跳过的代价是后面反复卡住</strong></td></tr><tr><td>攒到最后才提交</td><td><code>git log</code> 里只有三次提交</td><td>每周至少提交两三次，按功能提交</td></tr><tr><td>不写文档，最后补</td><td>第 12 周发现记不清当初怎么做的了</td><td><strong>边做边记。</strong> 联调记录当场写，不要事后回忆</td></tr><tr><td>等到最后才部署</td><td>最后一天发现子路由 404，没时间修</td><td>第 12 周第一天就部署上去</td></tr><tr><td>只做功能不做优化</td><td>首屏 3 MB，答辩时被问住了</td><td>优化在第 12 周做，但<strong>从第 4 周起就不要引入大依赖</strong></td></tr></tbody></table><details class="details custom-block"><summary>“一次做完一个模块”为什么这么重要</summary><p>有同学的做法是：五个模块同时开工，每个模块都做到一半。</p><p><strong>问题在于“一半”的东西不能验证：</strong></p><ul><li>活动列表做到一半 —— 分页还没做，没法确认接口返回的 <code>total</code> 对不对</li><li>报名审核做到一半 —— 审核操作还没做，没法确认名额联动对不对</li><li>场次安排做到一半 —— 冲突检测还没做，没法确认时段规则理解得对不对</li></ul><p><strong>半个功能验证不出任何东西。</strong> 而一个做完的功能，能立刻验证出“我对需求的理解对不对”。</p><p><strong>如果理解错了，早做完成早发现。</strong> 五个半成品同时被推翻，比一个成品被推翻要痛苦得多。</p><p><strong>具体建议的顺序</strong>：活动管理（列表 → 表单 → 详情）→ 报名审核 → 场次与场地 → 数据看板 → 登录鉴权（这个可以提前，因为它很简单且是其他模块的前置）。</p></details><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>分阶段交付的目的是让问题尽早暴露</strong>，不是增加工作量。</li><li><strong>阶段一不写业务代码</strong>，只写清单、搭骨架、配规范。它的产出在第 11 周才见效，但那时收益最大。</li><li><strong>阶段二每周的案例练习拼起来就是项目。</strong> 认真做完案例，第 11 周时项目应该已经完成七八成。</li><li><strong>第 5、6 周是最容易落后的时间点</strong>，因为内容量最大。落后了就降低项目部分的完成度，先保证案例做完。</li><li><strong>阶段三的实际工作是“把散着做的页面装进一个完整的壳里”</strong>：接真实接口、装进布局、抽出规则、整理路由。</li><li><strong>部署和答辩 PPT 不能拖到最后一天。</strong> 它们的失败可以提前发现，成本很低。</li><li><strong>“一次做完一个模块”比“五个模块各做一半”强得多。</strong> 半个功能验证不出任何东西。</li><li><strong>每周填一次自查清单，尤其是“卡住超过两小时的问题”这一项。</strong> 硬撑的代价大于问人。</li><li><strong>先做功能，后做样式。</strong> 前两周反复调颜色是最常见的浪费。</li><li><strong>用户端是延伸，不是必修。</strong> 管理端没交付完之前不要开第二个端 —— 两个半成品不如一个成品。</li><li><strong>用 AI 写代码不等于可以不读代码。</strong> 每周自查里那一条“这周写的代码我都读过、能解释吗”， 答不上来就要回头补。具体做法见<a href="/frontend-engineering-course/project/ai-collaboration.html">项目 AI 协作规范</a>。</li></ul><hr><p>上一页：<a href="/frontend-engineering-course/project/structure.html">目录结构与命名约定</a> · 下一页：<a href="/frontend-engineering-course/project/ai-collaboration.html">AI 协作规范</a></p>',82)])])}const u=d(o,[["render",l]]);export{b as __pageData,u as default};
